  "sql": "SELECT md.chembl_id AS compound_chembl_id, cs.canonical_smiles, cr.compound_key, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi) AS pubmed_id_or_doi, a.description AS assay_description, act.standard_type, act.standard_relation, act.standard_value, act.standard_units, act.activity_comment, td.chembl_id AS target_chembl_id, td.pref_name AS target_name, td.organism AS target_organism FROM molecule_dictionary md JOIN compound_structures cs ON md.molregno = cs.molregno JOIN compound_records cr ON md.molregno = cr.molregno JOIN docs d ON cr.doc_id = d.doc_id JOIN activities act ON cr.record_id = act.record_id JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary td ON a.tid = td.tid WHERE td.chembl_id = 'CHEMBL5251' AND act.standard_type = 'IC50' AND cs.canonical_smiles IS NOT NULL AND (d.pubmed_id IS NOT NULL OR d.doi IS NOT NULL) ORDER BY md.chembl_id ASC, cs.canonical_smiles ASC, cr.compound_key ASC, COALESCE(CAST(d.pubmed_id AS TEXT), d.doi) ASC, a.description ASC, act.standard_type ASC, act.standard_relation ASC, act.standard_value ASC, act.standard_units ASC, act.activity_comment ASC, td.chembl_id ASC, td.pref_name ASC, td.organism ASC"
